#!/bin/sh
# Simulate HandheldNes (as generated by the last build) with tb_system.sv in xsim.
# Usage: run_system.sh <rom.nes> <workdir> [xsim plusargs, no '=' ...]
#   e.g. run_system.sh "Balloon Fight (USA).nes" /tmp/nes-sys +frames12 +dump_from4 +dump_every2
# Needs Vivado's bin directory on PATH and fpga/build/nes/generated from a build
# (or a mill elaboration into that directory).
set -e
HERE=$(cd "$(dirname "$0")" && pwd)
RTL="${NES_RTL:-$HERE/../../rtl}"
GEN="$HERE/../../../../build/nes/generated"
ROM="$1"; WORK="$2"; shift 2
mkdir -p "$WORK"
python "$HERE/../make_rom_hex.py" "$ROM" "$WORK"
cd "$WORK"
if [ ! -f xsim.dir/tb_system_snap/xsimk.exe ] || [ -n "$REBUILD" ]; then
  xvhdl "$RTL/bus_savestates.vhd" "$RTL/t65/T65_Pack.vhd" "$RTL/t65/T65_ALU.vhd" "$RTL/t65/T65_MCode.vhd" \
        "$RTL/t65/T65.vhd" "$RTL/savestates.vhd" "$RTL/statemanager.vhd" > xvhdl.log
  GENFILES=""
  for f in MMCM PLL NesRomInfo MemoryArbiter SramHostAdapter PipelineMemoryArbiter PipelineInterfaceBridge \
           NesSaveSlotScanner NesSaveStatePort mem_32768x8 NesCartRam mem_2048x8 NesDualPortRam cache_sram_1024x140 \
           LineReadCache LineBuffer PipelineMemoryLowPriorityMux ram_4x29 Queue4_Request BytePortBridge \
           NesVideoCapture NesJoypad ButtonFilter AudioDecimator ram_256x32 Queue256_Sample AudioRateAdapter \
           ODDRWrapper AsyncSramController HandheldNes; do
    GENFILES="$GENFILES $GEN/$f.sv"
  done
  xvlog -sv --relax "$HERE/sim_defines.v" "$RTL/regs_savestates.sv" "$RTL/apu.sv" "$RTL/ppu.sv" "$RTL/mappers/MMC1.sv" "$RTL/mappers/MMC2.sv" \
        "$RTL/mappers/MMC3.sv" "$RTL/mappers/generic.sv" "$RTL/cart.sv" "$RTL/nes.sv" \
        $GENFILES "$HERE/sim_primitives.v" "$HERE/sdram_path_stub.sv" "$HERE/tb_system.sv" > xvlog.log
  xelab --relax -debug off -O3 tb_system -s tb_system_snap > xelab.log
fi
xsim tb_system_snap -R --testplusarg "file_size$(cat file_size.txt)" $(for a in "$@"; do printf -- '--testplusarg %s ' "${a#+}"; done) > xsim.log 2>&1
tail -20 xsim.log
